css:
/* Shared control language: 44px targets, quiet outlines, circular icon actions. */
.ds-button {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  min-height:var(--control-height);
  padding:10px 18px;
  border:1px solid var(--color-hairline-strong);
  border-radius:var(--radius-pill);
  background:var(--color-paper);
  color:var(--color-ink);
  font:500 14px/22px var(--font-sans);
  text-decoration:none;
  white-space:nowrap;
  flex-shrink:0;
  text-align:center;
  cursor:pointer;
  transition:background-color var(--dur-fast) ease,border-color var(--dur-fast) ease,color var(--dur-fast) ease,transform 100ms var(--ease-out);
}
.ds-button svg { flex-shrink:0; width:var(--control-icon-size); height:var(--control-icon-size); stroke-width:var(--control-icon-stroke); transition:transform var(--dur-fast) var(--ease-out); }
.ds-primary { background:var(--color-ink); border-color:var(--color-ink); color:var(--color-paper); }
.ds-ghost { background:transparent; border-color:transparent; color:var(--color-ink-soft); padding-inline:12px; }
.ds-subtle { background:var(--color-plate); border-color:transparent; }
.ds-icon { width:var(--control-height); height:var(--control-height); padding:0; border-radius:50%; }
.ds-button:focus-visible { outline:2px solid var(--color-ink); outline-offset:3px; }
.ds-button:active:not(:disabled):not([aria-disabled='true']) { transform:scale(.96); }
.ds-button:disabled,.ds-button[aria-disabled='true'] { opacity:.35; cursor:default; transform:none; }
.ds-button[aria-pressed='true'] { background:var(--color-ink); color:var(--color-paper); border-color:var(--color-ink); }
@media (hover:hover) and (pointer:fine) {
  .ds-button:hover:not(:disabled):not([aria-disabled='true']) { background:var(--color-plate); border-color:var(--color-border-hover); color:var(--color-ink); }
  .ds-primary:hover:not(:disabled):not([aria-disabled='true']) { background:var(--color-accent); border-color:var(--color-accent); color:var(--color-paper); }
  .ds-ghost:hover:not(:disabled):not([aria-disabled='true']) { background:var(--color-subtle); border-color:transparent; }
  .ds-button[data-direction='previous']:hover:not(:disabled):not([aria-disabled='true']) svg { transform:translateX(-2px); }
  .ds-button[data-direction='next']:hover:not(:disabled):not([aria-disabled='true']) svg { transform:translateX(2px); }
}
@media (prefers-reduced-motion:reduce) { .ds-button,.ds-button svg { transition:none; } .ds-button:active:not(:disabled),.ds-button:hover:not(:disabled) svg { transform:none; } }
@media (forced-colors:active) { .ds-button { border-color:ButtonText; } .ds-button:disabled,.ds-button[aria-disabled='true'] { opacity:1; color:GrayText; border-color:GrayText; } }
html[data-input='keyboard'] .ds-button:active { transform:none; }
